<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><title>{{ ui_text('examinations.copy.admit_card_verification_examcell') }}</title><x-assets /></head><body><main class="public-state"><x-card class="verification-card"><div class="card-body"><x-logo wordmark :size="40"/><p class="eyebrow verification-eyebrow">{{ ui_text('examinations.copy.official_admit_card_verification') }}</p><h1>{{ $valid?'Valid admit card':'Admit card is not currently valid' }}</h1><div class="verification-status"><x-badge :status="$valid?'Valid':'Invalid'"/></div><dl class="verification-details"><div><dt>{{ ui_text('examinations.copy.student_name') }}</dt><dd>{{ $studentName }}</dd></div><div><dt>{{ ui_text('examinations.copy.roll_number') }}</dt><dd>{{ $rollNumber }}</dd></div><div><dt>{{ ui_text('examinations.copy.examination') }}</dt><dd>{{ $examName }}</dd></div><div><dt>{{ ui_text('examinations.copy.validity_status') }}</dt><dd>{{ $valid?'Valid':'Invalid' }}</dd></div></dl><p class="muted text-xs">{{ $valid?'This card matches an active, published examination record.':'This card does not currently meet the examination cell’s validity requirements. Contact the examination cell.' }}</p></div></x-card></main></body></html>
